import threading

def find_min_max(arr):
    """Find min and max of arr. arr must not be mutated during this call."""
    if not arr:
        return None, None
    min_val = max_val = arr[0]
    for val in arr[1:]:
        if val < min_val:
            min_val = val
        if val > max_val:
            max_val = val
    return min_val, max_val


class MinMaxTracker:
    """Thread-safe min/max tracker over a shared, mutable collection."""

    def __init__(self):
        self._lock = threading.Lock()
        self._data = []

    def add(self, value):
        with self._lock:
            self._data.append(value)

    def remove(self, value):
        with self._lock:
            self._data.remove(value)

    def get_min_max(self):
        with self._lock:
            # Snapshot under the lock so iteration is safe
            snapshot = list(self._data)
        return find_min_max(snapshot)

